INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('zhao-warring','赵','["赵","赵国"]',NULL,'{"periods":[{"rank":"侯","start":{"year":-403,"month":1,"confidence":"year"},"end":{"year":-300,"month":12,"confidence":"year"}},{"rank":"王","start":{"year":-299,"month":1,"confidence":"year"},"end":{"year":-228,"month":12,"confidence":"year"}}]}','cn','east_asia',-403,1,NULL,'year',-228,12,NULL,'year',-4824,-2713,'ochre',NULL,NULL,'赵氏原为晋国卿族，前453年与韩、魏瓜分智氏领地，前403年赵烈侯获周天子册命为诸侯。初都中牟，前386年迁邯郸，武灵王时期推行胡服骑射并向北扩张；前228年秦攻陷邯郸、俘赵王迁。赵嘉另在代地续立，前222年为秦所灭。');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-lie','籍','zhao-warring','["赵烈侯"]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','赵献侯之子，继承赵氏在晋国的卿族势力。此前赵襄子于前453年联合韩、魏灭智氏，赵氏又据有代地；烈侯时以中牟为统治中心，前403年与魏、韩同获周天子册封为诸侯。邯郸成为赵都在后来的赵敬侯时期。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵烈侯"}]','烈',NULL,'烈侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-r1','','zhao-warring','["赵武侯"]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','烈侯之子，武侯。在位十三年，名失考，事迹不详，国势平稳，无力争霸，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵武侯"},{"label":"《史记·赵世家》","url":"https://ctext.org/shiji/zhao-shi-jia/zh"}]','武',NULL,'武侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-r2','章','zhao-warring','["赵敬侯"]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','敬侯，迁都邯郸，赵国势力东移。在位十二年，国势渐起，为后世霸业奠基，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵敬侯"}]','敬',NULL,'敬侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-r3','种','zhao-warring','["赵成侯"]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','成侯，曾与韩魏分晋，俘虏晋君。在位二十五年，国势尚可，无力争霸，事迹载于《史记》相关记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵成侯"}]','成',NULL,'成侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-r4','语','zhao-warring','["赵肃侯"]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','肃侯，时赵魏大战，赵国中衰。壮志未酬而卒，传位武灵王，国势转弱，事迹载于《史记》相关记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵肃侯"}]','肃',NULL,'肃侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-r5','雍','zhao-warring','["赵武灵王"]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','推行胡服骑射，灭中山，拓土云中、雁门、代郡。沙丘之乱中被幽禁饿死，赵国由盛转衰，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵武灵王"},{"label":"《史记·赵世家》","url":"https://zh.wikisource.org/zh-hans/史記/卷043"},{"label":"《资治通鉴》卷3","url":"https://zh.wikisource.org/zh-hans/資治通鑑/卷003"}]','武灵',NULL,'武灵王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-r6','何','zhao-warring','["赵惠文王"]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','武灵王之子，惠文王。杀忠臣肥义，秦赵长平之战惨败，国力大损，国势危急，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵惠文王"},{"label":"《史记·赵世家》","url":"https://zh.wikisource.org/zh-hans/史記/卷043"},{"label":"《资治通鉴》卷3","url":"https://zh.wikisource.org/zh-hans/資治通鑑/卷003"}]','惠文',NULL,'惠文王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-r7','丹','zhao-warring','["赵孝成王"]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','孝成王，在位时赖名将李牧支撑赵国。长平之后赵国元气大伤，国势危急，无力争霸，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵孝成王"}]','孝成',NULL,'孝成王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-r8','偃','zhao-warring','["赵悼襄王"]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','悼襄王，在位九年。秦国连破赵国，国势危急，割地求和，濒临灭亡，事迹载于《史记》相关记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵悼襄王"}]','悼襄',NULL,'悼襄王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-r9','迁','zhao-warring','["赵幽缪王"]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','幽缪王，赵国末代君主。前228年秦灭赵，公子嘉逃代自立，旋亦亡，赵国终结，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵幽缪王"}]','幽缪',NULL,'幽缪王','[]');
