INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('zhao-huiwen-royal-accession','赵惠文王以王号受国','politics','point','year',NULL,NULL,'《史记·赵世家》武灵王二十七年五月戊申大朝、立何为王；农历月日未可靠换算，按年精度。采用惠文王王年起点，不断言武灵王此前从未使用王称。',-299,12,NULL,-3565,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-299年，赵武灵王将国政交给王子何，何以王号即位，是为赵惠文王，武灵王自号主父。此前武灵王曾在列国相王时表示不愿徒有王名；胡服骑射及向中山、北方扩张之后，他选择由新王治理国政，自己继续领兵经营边疆。此次传国明确使用王号，并形成主父与在位国王并存的权力格局。',NULL,NULL,'[{"label":"《史记·赵世家》","url":"https://zh.wikisource.org/zh-hans/史記/卷043"},{"label":"《资治通鉴》卷3","url":"https://zh.wikisource.org/zh-hans/資治通鑑/卷003"}]');
